answer = []
for source in sources:
    draft = dict(drafts[source['number']])
    fragment = draft.pop('fragment')
    item = {
        field: source[field]
        for field in ('code_id', 'source_id', 'source_sha256', 'number')
    }
    item['proposed_xml'] = Path('fragments', fragment).read_text().strip()
    item.update(draft)
    item['status'] = 'rewrite_draft'
    answer.append(item)

Path('answer.json').write_text(json.dumps(answer, ensure_ascii=False, indent=2) + '\n')
